package backfill.data;

import org.fog.entities.Tuple;

/**
 * A data unit held in an edge server's egress buffer, carrying its simulation-time metadata.
 */
public final class EgressUnit {

    public final Tuple tuple;
    /** Sim time when the unit was generated by the edge. Order-by-generation anchor. */
    public final double genTime;
    /** true = generated while connected ("new data"); false = generated during an outage ("accumulated data"). */
    public final boolean isNew;
    public final int edgeIndex;

    public EgressUnit(Tuple tuple, double genTime, boolean isNew, int edgeIndex) {
        this.tuple = tuple;
        this.genTime = genTime;
        this.isNew = isNew;
        this.edgeIndex = edgeIndex;
    }

    public int cloudletId() { return tuple.getCloudletId(); }
    public double fileSize() { return tuple.getCloudletFileSize(); }
}
